#!/usr/bin/env bash
# Build the one-page resume PDF (public/resume.pdf) from design/resume.html.
#
# Why this exists instead of the career-ops pipeline:
#   career-ops' generate-pdf.mjs renders an ATS-first CV from a template —
#   single column, standard section headers, no visual identity. That is the
#   right document for a job portal and the wrong one for a portfolio's
#   "Resume" button. This builds a designed one-pager that uses the site's
#   own Vercel tokens, so it reads as part of iankitkumar.in.
#
#   The ATS-friendly two-page CV is still generated by career-ops
#   (node generate-pdf.mjs) and stays available for job applications.
#
# Facts: every claim in design/resume.html traces to career-ops/cv.md.
# Run `node verify-cv-facts.mjs` against the built HTML to re-check.
#
# Usage: bash scripts/build-resume.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
cd "$PROJECT_DIR"

SRC_HTML="design/resume.html"
SRC_CSS="design/resume.css"
PHOTO="design/resume-photo.png"
OUT_HTML="$PROJECT_DIR/.resume-build.html"
OUT_PDF="$PROJECT_DIR/public/resume.pdf"

# Font sources: the full Geist / Geist Mono TTFs, one per weight.
# Google's "latin" subset woff2 omits U+2192 (the arrow used in the role
# line), which silently rendered in Liberation Sans inside the PDF.
FONT_DIR="${RESUME_FONT_DIR:-$HOME/.local/share/fonts/geist}"
GEIST_400="$FONT_DIR/Geist-Regular.ttf"
GEIST_500="$FONT_DIR/Geist-Medium.ttf"
GEIST_600="$FONT_DIR/Geist-SemiBold.ttf"
GEIST_MONO_400="$FONT_DIR/GeistMono-Regular.ttf"
GEIST_MONO_500="$FONT_DIR/GeistMono-Medium.ttf"

for f in "$SRC_HTML" "$SRC_CSS" "$PHOTO" "$GEIST_400" "$GEIST_500" "$GEIST_600" \
         "$GEIST_MONO_400" "$GEIST_MONO_500"; do
  [[ -f "$f" ]] || { echo "ERROR: missing $f" >&2; exit 2; }
done

echo "[1/4] inlining fonts and photo..."
python3 - "$SRC_HTML" "$SRC_CSS" "$PHOTO" "$OUT_HTML" \
  "$GEIST_400" "$GEIST_500" "$GEIST_600" "$GEIST_MONO_400" "$GEIST_MONO_500" <<'PY'
import base64, pathlib, sys

html_p, css_p, photo_p, out_p = sys.argv[1:5]
g400, g500, g600, m400, m500 = sys.argv[5:10]

def data_uri(path, mime):
    return f"data:{mime};base64," + base64.b64encode(pathlib.Path(path).read_bytes()).decode()

html = pathlib.Path(html_p).read_text(encoding="utf-8")
html = html.replace("__CSS__", pathlib.Path(css_p).read_text(encoding="utf-8"))
html = html.replace("__GEIST_400__", data_uri(g400, "font/ttf"))
html = html.replace("__GEIST_500__", data_uri(g500, "font/ttf"))
html = html.replace("__GEIST_600__", data_uri(g600, "font/ttf"))
html = html.replace("__GEIST_MONO_400__", data_uri(m400, "font/ttf"))
html = html.replace("__GEIST_MONO_500__", data_uri(m500, "font/ttf"))
html = html.replace("__PHOTO__", data_uri(photo_p, "image/png"))

# A data: URI in an <img src> is fine, but keep the HTML self-contained.
pathlib.Path(out_p).write_text(html, encoding="utf-8")
print(f"  wrote {out_p} ({len(html):,} bytes)")
PY

echo "[2/4] printing A4..."
chromium --headless --disable-gpu --no-sandbox --hide-scrollbars \
  --no-pdf-header-footer \
  --virtual-time-budget=10000 \
  --print-to-pdf-no-header \
  --print-to-pdf="$OUT_PDF" \
  "file://$OUT_HTML" 2>&1 | grep -v "^$" | tail -2 || true

if [[ ! -s "$OUT_PDF" ]]; then
  echo "ERROR: PDF was not produced" >&2
  exit 3
fi

# Normalise the PDF metadata so the build is byte-reproducible.
#
# Chromium stamps CreationDate/ModDate into every PDF, so two builds of
# identical content produce different bytes. The site's resume URL carries
# a sha256 of this file, so without this the ?v= query changes on every
# rebuild even when nothing about the CV changed - which defeats the point
# of content-addressing it and churns the cache for no reason.
#
# qpdf normalises the document id and we overwrite the dates with a fixed
# epoch. Result: identical input always yields identical bytes.
echo "    normalising PDF metadata for reproducibility"
if command -v uv >/dev/null 2>&1; then
  uv run --quiet --with pikepdf python - "$OUT_PDF" <<'PY'
import os, pikepdf, sys

path = sys.argv[1]
tmp = path + ".normalised"
pdf = pikepdf.open(path)
# A fixed epoch, not "now". The point is that two builds of the same
# content produce the same bytes.
pdf.docinfo["/CreationDate"] = "D:20260101000000Z"
pdf.docinfo["/ModDate"] = "D:20260101000000Z"
pdf.save(tmp, deterministic_id=True, compress_streams=True)
pdf.close()
os.replace(tmp, path)
PY
else
  echo "    WARNING: uv not found, PDF will not be byte-reproducible"
fi

echo "[3/4] verifying..."
PAGES="$(pdfinfo "$OUT_PDF" | awk '/^Pages:/ {print $2}')"
DIMS="$(pdfinfo "$OUT_PDF" | awk -F': +' '/^Page size:/ {print $2}')"
BYTES="$(stat -c '%s' "$OUT_PDF")"

if [[ "$PAGES" != "1" ]]; then
  echo "ERROR: expected 1 page, got $PAGES" >&2
  echo "  Trim content in design/resume.html until it fits." >&2
  exit 4
fi

# Extract once into a variable. Piping pdftotext straight into `grep -q`
# breaks under `set -o pipefail`: grep exits on the first match, pdftotext
# takes SIGPIPE, and the pipeline reports failure even though the content
# is present.
PDF_TEXT="$(pdftotext "$OUT_PDF" -)"

if ! grep -q "Pune, India" <<<"$PDF_TEXT"; then
  echo "ERROR: rendered PDF is missing expected content" >&2
  exit 5
fi

# The public CV must not carry the partner's details or the relocation city.
if grep -qiE "pooja|1779185356|heidelberg" <<<"$PDF_TEXT"; then
  echo "ERROR: third-party data leaked into the public PDF" >&2
  exit 6
fi

echo "  OK  1 page, $DIMS, ${BYTES} bytes"

echo "[4/4] fact check against career-ops/cv.md"
CV_MD="${CAREER_OPS_ROOT:-/home/anki/share/JobApplications/career-ops}/cv.md"
if [[ -f "$CV_MD" ]] && [[ -d "${CAREER_OPS_ROOT:-/home/anki/share/JobApplications/career-ops}" ]]; then
  ( cd "${CAREER_OPS_ROOT:-/home/anki/share/JobApplications/career-ops}" \
    && node verify-cv-facts.mjs "$OUT_HTML" --source cv.md ) && echo "  fact check passed"
else
  echo "  skipped (career-ops not found at $CV_MD)"
fi

rm -f "$OUT_HTML"
echo "Done: $OUT_PDF"
